mapper.select:
select id, name, discnt_time,
       phone, email, auth, car_num, car_type
from member
where id=#{id}
  and pw=#{pw}

mapper.update:
update member
set pw=#{pw}
where id=#{id}

update member
set phone=#{phone}
where id=#{id}

update member
set email=#{email}
where id=#{id}

update member
set car_num=#{car_num},
    car_type=#{car_type}
where id=#{id}
